schema_version: 1
name: api-incident-grader
note: Hit an API status page; rate any failure; hand unclear cases to a person.
owner: team
inputs:
  endpoint: {type: string, description: API status page}
pipeline:
  trigger: {type: schedule, every: 2m}
  steps:
    - name: check
      input: text
      uses: http
      with: {url: '{{endpoint}}'}
      on: {failed: grade, down: grade, up: stop}
    - name: grade
      input: text
      run: >-
        python3 -c 'import json, sys; c = json.load(sys.stdin);
        print("high" if c["status"] >= 502 or c["latency_ms"] > 5000 else "low", "http", c["status"])'
      on: {failed: stop, done: next}
    - name: decide
      input: text
      uses: ask
      with: {question: 'Is this a short blip or a real incident?', buckets: [blip, incident]}
      on: {blip: stop, incident: next}
  result: {to: notify}

schema_version: 1
name: health-triage
note: Probe a URL; classify failures; escalate unknowns.
owner: team
inputs:
  url: {type: string, description: Service health endpoint}
pipeline:
  trigger: {type: schedule, every: 60s}
  steps:
    - name: probe
      input: text
      uses: http
      with: {url: '{{url}}'}
      on: {up: stop, down: measure, failed: measure}
    - name: measure
      input: text
      run: >-
        python3 -c 'import json, sys; p = json.load(sys.stdin);
        print("high" if p["status"] >= 500 or p["latency_ms"] > 2000 else "low", "status", p["status"])'
      on: {done: next, failed: stop}
    - name: triage
      input: text
      uses: ask
      with: {question: 'Is this a transient blip or an outage?', buckets: [transient, outage]}
      on: {transient: stop, outage: next}
  result: {to: notify}

schema_version: 1
name: plan-signoff-advisor
note: Look for uncovered spec parts and advise; a person does the final sign-off.
inputs:
  plan_id: {type: string, description: Plan id}
pipeline:
  trigger: {type: input, kind: text, source: {text: review}}
  steps:
    - {name: holes, input: text, run: "codeterm plan gaps '{{plan_id}}' --json --all", on: {failed: rework}}
    - {name: complete, input: text, uses: filter, with: {bucket: empty, pattern: '"gaps":\s*\[\]'}, on: {failed: rework, empty: next, done: next}}
    - {name: judge, input: text, uses: ask, with: {buckets: [go, rework], question: 'Does a verified task back each spec section?'}, on: {go: stop, other: rework, rework: next}}
    - {name: rework, input: text, run: echo plan-rework-needed, on: {failed: stop, done: stop}}
  result: {to: notify}

schema_version: 1
name: plan-review-gate
note: Check plan coverage and recommend; the human runs plan approve.
inputs:
  plan: {type: string, description: Plan id}
pipeline:
  trigger: {type: input, kind: text, source: {text: go}}
  steps:
    - {name: gaps, input: text, run: "codeterm plan gaps '{{plan}}' --json", on: {failed: revise}}
    - {name: covered, input: text, uses: filter, with: {pattern: '"gaps": \[\]', bucket: full}, on: {full: next, done: next, failed: revise}}
    - {name: verdict, input: text, uses: ask, with: {question: 'Is every section covered by a tested task?', buckets: [ready, revise]}, on: {ready: stop, revise: next, other: revise}}
    - {name: revise, input: text, run: echo plan-needs-revision, on: {done: stop, failed: stop}}
  result: {to: notify}

schema_version: 1
name: ship-gate
note: Refuse to ship while the capability graph is invalid or old worktrees linger.
inputs:
  plan_id: {type: string, description: Plan id}
  checkout: {type: string, description: Canonical checkout}
pipeline:
  trigger: {type: input, kind: text, source: {text: start}}
  steps:
    - {name: graph, input: text, run: "codeterm essence-map validate --root '{{checkout}}' --strict", on: {failed: refuse}}
    - {name: worktrees, input: text, run: "codeterm plan lanes '{{plan_id}}' --stale --json", on: {failed: refuse}}
    - {name: none-left, input: text, uses: filter, with: {bucket: tidy, pattern: '"stale": \[\]'}, on: {tidy: next, failed: refuse, done: refuse}}
    - {name: notes, input: text, run: "codeterm essence-map release-summary --root '{{checkout}}' --since decision-1", on: {failed: refuse, done: stop}}
    - {name: refuse, input: text, run: echo ship-refused, on: {failed: stop, done: stop}}
  result: {to: notify}

schema_version: 1
name: release-preflight
note: Block a release until map and lanes are clean.
inputs:
  root: {type: string, description: Canonical checkout}
  plan: {type: string, description: Plan id}
pipeline:
  trigger: {type: input, kind: text, source: {text: go}}
  steps:
    - {name: map, input: text, run: "codeterm essence-map validate --root '{{root}}'", on: {failed: blocked}}
    - {name: lanes, input: text, run: "codeterm plan lanes '{{plan}}' --stale", on: {failed: blocked}}
    - {name: clean, input: text, uses: filter, with: {pattern: '(?m)^no stale lanes$', bucket: ok}, on: {ok: next, done: blocked, failed: blocked}}
    - {name: summary, input: text, run: "codeterm essence-map release-summary --root '{{root}}'", on: {done: stop, failed: blocked}}
    - {name: blocked, input: text, run: echo release-blocked, on: {done: stop, failed: stop}}
  result: {to: notify}
